const enc = new TextEncoder();
const hex = b => [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, "0")).join("");
const unhex = h => new Uint8Array((String(h).match(/../g) || []).map(x => parseInt(x, 16)));
const sha256 = async s => hex(await crypto.subtle.digest("SHA-256", enc.encode(s)));
const J = (o, c = 200, h = {}) => new Response(JSON.stringify(o), { status: c, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", ...h } });
const bad = (m, c = 400) => J({ error: m }, c);
const fmtD = d => { try { return new Date(d).toLocaleString("az-AZ", { timeZone: "Asia/Baku" }); } catch (e) { return new Date(d).toISOString(); } };
const ipOf = req => req.headers.get("CF-Connecting-IP") || "";
function eq(a, b) { a = String(a); b = String(b); if (a.length !== b.length) return false; let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0; }

// ---------- şifrə (PBKDF2). Pulsuz planda CPU limiti 10ms olduğu üçün say PBKDF2_ITER ilə dəyişir ----------
async function pbk(p, salt, it) { const k = await crypto.subtle.importKey("raw", enc.encode(p), "PBKDF2", false, ["deriveBits"]); return new Uint8Array(await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: it }, k, 256)); }
const ITER = env => Math.max(1000, parseInt(env.PBKDF2_ITER || "10000", 10) || 10000);
async function hash(p, env) { const s = crypto.getRandomValues(new Uint8Array(16)), it = ITER(env); return "p$" + it + "$" + hex(s) + "$" + hex(await pbk(p, s, it)); }
async function check(p, h) { const [, it, s, k] = String(h).split("$"); if (!k) return false; return eq(hex(await pbk(p, unhex(s), +it)), k); }

// ---------- baza miqrasiyası (köhnə bazanı özü yeniləyir) ----------
let migrated = false;
async function migrate(env) {
  if (migrated) return; const DB = env.DB;
  await DB.batch([
    DB.prepare("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,email TEXT UNIQUE,pass TEXT,bal INTEGER DEFAULT 0,admin INTEGER DEFAULT 0,created INTEGER,last_login INTEGER,last_seen INTEGER,blocked INTEGER DEFAULT 0,seen_at INTEGER DEFAULT 0,username TEXT)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS sessions(h TEXT PRIMARY KEY,uid INTEGER,exp INTEGER)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY,pf TEXT,name TEXT,price INTEGER,min INTEGER,max INTEGER,fixed INTEGER DEFAULT 0)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER,email TEXT,date INTEGER,svc TEXT,link TEXT,qty INTEGER,cost INTEGER,status TEXT,upd INTEGER DEFAULT 0,acct TEXT,note TEXT)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS tx(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER,amt INTEGER,date INTEGER,ref TEXT)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS topups(id TEXT PRIMARY KEY,uid INTEGER,amt INTEGER,status TEXT,date INTEGER,trx TEXT)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT,date INTEGER,level TEXT,msg TEXT)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY,v TEXT)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER,type TEXT,date INTEGER,ip TEXT)"),
    DB.prepare("CREATE TABLE IF NOT EXISTS attempts(ip TEXT,t INTEGER)")]);
  const cols = async t => (await DB.prepare("SELECT name FROM pragma_table_info('" + t + "')").all()).results.map(r => r.name);
  const add = async (t, c, d) => { if (!(await cols(t)).includes(c)) await DB.prepare("ALTER TABLE " + t + " ADD COLUMN " + c + " " + d).run(); };
  await add("users", "last_login", "INTEGER"); await add("users", "last_seen", "INTEGER"); await add("users", "blocked", "INTEGER DEFAULT 0"); await add("users", "seen_at", "INTEGER DEFAULT 0");
  await add("orders", "upd", "INTEGER DEFAULT 0"); await add("services", "fixed", "INTEGER DEFAULT 0");
  await add("users", "username", "TEXT"); await add("orders", "acct", "TEXT"); await add("orders", "note", "TEXT"); await add("topups", "trx", "TEXT");
  await DB.prepare("UPDATE users SET username=lower(email) WHERE username IS NULL OR username=''").run();
  await DB.prepare("CREATE UNIQUE INDEX IF NOT EXISTS idx_users_username ON users(username)").run();
  if (!(await DB.prepare("SELECT v FROM meta WHERE k='seed1'").first())) { // ilk quraşdırma: xidmətlər siyahısı
    if ((await DB.prepare("SELECT COUNT(*) c FROM services").first()).c === 0)
      for (let i = 0; i < SEED.length; i += 40) await DB.batch(SEED.slice(i, i + 40).map(r => DB.prepare("INSERT OR IGNORE INTO services(id,pf,name,price,min,max) VALUES(?,?,?,?,?,?)").bind(...r)));
    await DB.prepare("INSERT OR REPLACE INTO meta(k,v) VALUES('seed1','1')").run();
  }
  if (!(await DB.prepare("SELECT v FROM meta WHERE k='pkg220'").first())) await DB.batch([
    DB.prepare("INSERT OR IGNORE INTO services(id,pf,name,price,min,max,fixed) VALUES(220,'Instagram','Ali Aylıq Aktivlik paketi',5048,1,1,1)"),
    DB.prepare("INSERT OR REPLACE INTO meta(k,v) VALUES('pkg220','1')")]);
  await DB.prepare("DELETE FROM events WHERE date<?").bind(Date.now() - 90 * 864e5).run();
  await DB.prepare("DELETE FROM logs WHERE date<?").bind(Date.now() - 30 * 864e5).run();
  migrated = true;
}

// ---------- sessiya, limit, admin ----------
const logErr = async (env, level, msg) => { try { await env.DB.prepare("INSERT INTO logs(date,level,msg) VALUES(?,?,?)").bind(Date.now(), level, String(msg).slice(0, 500)).run(); } catch (e) { console.error("logErr", e); } };
const log = (env, uid, type, req) => env.DB.prepare("INSERT INTO events(uid,type,date,ip) VALUES(?,?,?,?)").bind(uid, type, Date.now(), ipOf(req)).run();
async function auth(req, env) {
  const m = /(?:^|; )sid=([a-f0-9]+)/.exec(req.headers.get("Cookie") || ""); if (!m) return null;
  const u = await env.DB.prepare("SELECT u.* FROM sessions s JOIN users u ON u.id=s.uid WHERE s.h=? AND s.exp>?").bind(await sha256(m[1]), Date.now()).first();
  if (!u || u.blocked === 1) return null;
  if (!u.last_seen || Date.now() - u.last_seen > 60000) await env.DB.prepare("UPDATE users SET last_seen=? WHERE id=?").bind(Date.now(), u.id).run();
  return u;
}
async function startSession(env, uid) {
  const t = hex(crypto.getRandomValues(new Uint8Array(32)));
  await env.DB.batch([env.DB.prepare("DELETE FROM sessions WHERE exp<?").bind(Date.now()), env.DB.prepare("INSERT INTO sessions(h,uid,exp) VALUES(?,?,?)").bind(await sha256(t), uid, Date.now() + 30 * 864e5), env.DB.prepare("UPDATE users SET last_login=?,last_seen=? WHERE id=?").bind(Date.now(), Date.now(), uid)]);
  return "sid=" + t + "; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=2592000";
}
async function limited(env, req, key = "", max = 15) {
  const ip = key + (ipOf(req) || "x"), n = Date.now();
  await env.DB.prepare("DELETE FROM attempts WHERE t<?").bind(n - 6e5).run();
  const c = await env.DB.prepare("SELECT COUNT(*) c FROM attempts WHERE ip=?").bind(ip).first();
  if (c.c >= max) return true;
  await env.DB.prepare("INSERT INTO attempts(ip,t) VALUES(?,?)").bind(ip, n).run(); return false;
}
let adminReady = false;
async function ensureAdmin(env) {
  if (adminReady) return;
  const au = (env.ADMIN_USER || "").trim().toLowerCase(), ap = env.ADMIN_PASS || "";
  if (!au || !ap) throw new Error("ADMIN_USER və ADMIN_PASS təyin edilməyib");
  if (ap.length < 12 || ap.toLowerCase().includes(au)) throw new Error("ADMIN_PASS zəifdir: minimum 12 simvol olmalı və istifadəçi adını ehtiva etməməlidir");
  const a = await env.DB.prepare("SELECT id,email,pass FROM users WHERE admin=1").first();
  if (!a) await env.DB.prepare("INSERT INTO users(name,username,email,pass,bal,admin,created) VALUES(?,?,?,?,0,1,?)").bind(au, au, au, await hash(ap, env), Date.now()).run();
  else if (a.email !== au || !(await check(ap, a.pass))) await env.DB.prepare("UPDATE users SET name=?,username=?,email=?,pass=? WHERE id=?").bind(au, au, au, await hash(ap, env), a.id).run();
  adminReady = true;
}

// ---------- ePoint ----------
const sign = async (env, data) => btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest("SHA-1", enc.encode(env.EPOINT_PRIVATE_KEY + data + env.EPOINT_PRIVATE_KEY)))));
async function creditTopup(env, t) { // bir ödəniş yalnız bir dəfə balansa yazılır
  await env.DB.batch([
    env.DB.prepare("UPDATE topups SET status='paid' WHERE id=? AND status<>'paid'").bind(t.id),
    env.DB.prepare("UPDATE users SET bal=bal+? WHERE id=? AND changes()>0").bind(t.amt, t.uid),
    env.DB.prepare("INSERT INTO tx(uid,amt,date,ref) SELECT ?,?,?,? WHERE changes()>0").bind(t.uid, t.amt, Date.now(), t.id)]);
}
async function epointResult(req, env) {
  const no = c => new Response("", { status: c });
  if (!env.EPOINT_PRIVATE_KEY) return no(400);
  const f = await req.formData().catch(() => null); if (!f) return no(400);
  const data = f.get("data"), sig = f.get("signature");
  if (!data || !sig || !eq(await sign(env, String(data)), String(sig))) { if (!(await limited(env, req, "cb:", 20))) await logErr(env, "warn", "ePoint bildirişi: yanlış imza rədd edildi"); return no(400); }
  let j; try { j = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(String(data)), c => c.charCodeAt(0)))); } catch (e) { return no(400); }
  const t = await env.DB.prepare("SELECT * FROM topups WHERE id=?").bind(String(j.order_id)).first(); if (!t) return no(404);
  if (j.status === "success") { if (Math.round(Number(j.amount) * 100) === t.amt) { if (j.transaction) await env.DB.prepare("UPDATE topups SET trx=? WHERE id=?").bind(String(j.transaction).slice(0, 80), t.id).run(); await creditTopup(env, t); } else await logErr(env, "warn", "ePoint: məbləğ uyğun gəlmir, ödəniş " + t.id); }
  else await env.DB.prepare("UPDATE topups SET status='failed' WHERE id=? AND status='pending'").bind(t.id).run();
  return new Response("OK");
}

// ---------- video yükləyicilər (üçüncü tərəf xidmətlər vasitəsilə) ----------
const TT_RE = /^https?:\/\/((www|vm|vt|m)\.)?tiktok\.com\/\S+$/i, IG_RE = /^https?:\/\/(www\.)?instagram\.com\/(p|reel|reels|tv)\/[\w-]+\S*$/i;
async function getJson(url, opt = {}) { const c = new AbortController(), t = setTimeout(() => c.abort(), 8000); try { return await (await fetch(url, { ...opt, signal: c.signal })).json(); } finally { clearTimeout(t); } }
function pick(o, keys, d = 0) { if (d > 6 || !o || typeof o !== "object") return ""; for (const k of keys) if (typeof o[k] === "string" && o[k]) return o[k]; for (const k in o) { const v = pick(o[k], keys, d + 1); if (v) return v; } return ""; }
function mp4s(o, out = [], d = 0) { if (d > 6 || out.length >= 5) return out; if (typeof o === "string") { if (o.startsWith("https://") && /\.mp4|video/i.test(o) && !out.includes(o)) out.push(o); } else if (o && typeof o === "object") for (const k in o) mp4s(o[k], out, d + 1); return out; }
async function dl(p, link, env, req) {
  const fail = () => bad("Video tapılmadı və ya xidmət müvəqqəti əlçatmazdır", 502), many = () => bad("Çox sorğu. Bir az sonra yenidən yoxlayın", 429);
  if (p === "tiktok") {
    if (link.length > 300 || !TT_RE.test(link)) return bad("Düzgün TikTok linki yazın");
    if (await limited(env, req, "dl:", 20)) return many();
    try {
      const j = await getJson((env.TIKTOK_API || "https://www.tikwm.com/api/") + "?hd=1&url=" + encodeURIComponent(link), { headers: { "User-Agent": "Mozilla/5.0" } });
      if (!j || j.code !== 0 || !j.data) return fail();
      const d = j.data, ab = x => x ? (String(x).startsWith("http") ? String(x) : "https://www.tikwm.com" + x) : "";
      return J({ title: String(d.title || "").slice(0, 200), author: String((d.author && d.author.nickname) || ""), hd: ab(d.hdplay), sd: ab(d.play), music: ab(d.music) });
    } catch (e) { return bad("Xidmətə qoşulmaq alınmadı", 502); }
  }
  if (p === "instagram") {
    if (link.length > 300 || !IG_RE.test(link)) return bad("Düzgün Instagram linki yazın (post və ya reel)");
    if (!env.IG_API_URL) return bad("Instagram yükləmə xidməti hələ qoşulmayıb", 503);
    if (await limited(env, req, "dl:", 20)) return many();
    try {
      let h = {}; try { h = JSON.parse(env.IG_API_HEADERS || "{}"); } catch (e) { }
      const j = await getJson(env.IG_API_URL.replace("{url}", encodeURIComponent(link)), { headers: h }), v = mp4s(j);
      if (!v.length) return fail();
      return J({ title: pick(j, ["title", "caption"]).slice(0, 200), author: "", hd: "", sd: v[0], music: "" });
    } catch (e) { return bad("Xidmətə qoşulmaq alınmadı", 502); }
  }
  return bad("Yanlış sorğu");
}
const csvCell = v => { v = String(v ?? ""); if (/^[\s=+\-@]/.test(v)) v = "'" + v; return '"' + v.replace(/"/g, '""') + '"'; };

// ---------- marşrutlar ----------
export default { async fetch(req, env) { try { return await route(req, env); } catch (e) { console.error(e); await logErr(env, "error", (e && e.message) || e); return bad("Server xətası", 500); } } };

async function route(req, env) {
  const p = new URL(req.url).pathname, post = req.method === "POST", DB = env.DB;
  if (p === "/" || p === "/index.html") return new Response(HTML, { headers: { "Content-Type": "text/html; charset=utf-8", ...SEC } });
  if (p === "/api/epoint/result" && post) return epointResult(req, env);
  if (!p.startsWith("/api/")) return new Response("Not found", { status: 404 });
  await migrate(env);
  if (post) { const o = req.headers.get("Origin"); let bad_o = false; try { bad_o = !!o && new URL(o).host !== new URL(req.url).host; } catch (e) { bad_o = true; } if (bad_o || req.headers.get("X-Requested-With") !== "lux") return bad("Yanlış sorğu", 403); }
  const b = post ? await req.json().catch(() => ({})) : {};
  const q = (sql, ...a) => DB.prepare(sql).bind(...a).all().then(r => r.results);

  if (p === "/api/state") {
    const u = await auth(req, env), sv = (await q("SELECT * FROM services ORDER BY id")).map(s => ({ id: s.id, pf: s.pf, name: s.name, price: s.price / 100, min: s.min, max: s.max, fixed: s.fixed === 1 }));
    if (!u) return J({ users: [], orders: [], tx: [], events: [], topups: [], logs: [], services: sv, session: null, unread: 0 });
    const A = u.admin === 1;
    const [us, os, tx, ev, tp, lg] = await Promise.all([
      A ? q("SELECT * FROM users ORDER BY id") : [u],
      A ? q("SELECT o.*,u.username AS uname FROM orders o LEFT JOIN users u ON u.id=o.uid ORDER BY o.id") : q("SELECT o.*,u.username AS uname FROM orders o LEFT JOIN users u ON u.id=o.uid WHERE o.uid=? ORDER BY o.id", u.id),
      A ? q("SELECT * FROM tx ORDER BY id") : q("SELECT * FROM tx WHERE uid=? ORDER BY id", u.id),
      A ? q("SELECT e.type,e.date,e.ip,u.name,u.email FROM events e LEFT JOIN users u ON u.id=e.uid ORDER BY e.id DESC LIMIT 300") : [],
      A ? q("SELECT t.id,t.amt,t.status,t.date,t.trx,u.email FROM topups t LEFT JOIN users u ON u.id=t.uid ORDER BY t.date DESC LIMIT 200") : [],
      A ? q("SELECT date,level,msg FROM logs ORDER BY id DESC LIMIT 200") : []]);
    const seen = u.seen_at || 0;
    return J({ session: u.id, services: sv, unread: A ? os.filter(o => o.date > seen).length : os.filter(o => (o.upd || 0) > seen).length,
      users: us.map(x => ({ id: x.id, name: x.name, username: x.username || "", email: x.email, admin: x.admin === 1, bal: x.bal / 100, created: x.created ? fmtD(x.created) : "", login: x.last_login ? fmtD(x.last_login) : "", seen: x.last_seen || 0, blocked: x.blocked === 1 })),
      orders: os.map(o => ({ id: o.id, uid: o.uid, email: o.email, user: o.uname || "", acct: o.acct || "", note: o.note || "", date: fmtD(o.date), svc: o.svc, link: o.link, qty: o.qty, cost: o.cost / 100, status: o.status, fresh: A ? o.date > seen : (o.upd || 0) > seen })),
      tx: tx.map(t => ({ uid: t.uid, amt: t.amt / 100, date: fmtD(t.date) })),
      topups: tp.map(t => ({ id: t.id, amt: t.amt / 100, status: t.status, date: fmtD(t.date), email: t.email || "", trx: t.trx || "" })),
      logs: lg.map(l => ({ date: fmtD(l.date), level: l.level, msg: l.msg })),
      events: ev.map(e => ({ type: e.type, date: fmtD(e.date), t: e.date, ip: e.ip || "", name: e.name || "", email: e.email || "" })) });
  }
  if (p === "/api/topup-status") {
    const a0 = await auth(req, env); if (!a0) return bad("Daxil olun", 401);
    const t = await DB.prepare("SELECT status,amt,date FROM topups WHERE uid=? ORDER BY date DESC LIMIT 1").bind(a0.id).first();
    return J(t ? { status: t.status, amt: t.amt / 100, age: Math.floor((Date.now() - t.date) / 1000) } : { status: "none", amt: 0, age: 0 });
  }
  if (p === "/api/admin/poll") {
    const a1 = await auth(req, env); if (!a1 || !a1.admin) return bad("İcazə yoxdur", 403);
    const c = await DB.prepare("SELECT COUNT(*) c FROM orders WHERE date>?").bind(a1.seen_at || 0).first();
    return J({ unread: c.c });
  }
  if (p === "/api/tiktok" || p === "/api/dl") { const sp = new URL(req.url).searchParams; return dl(p === "/api/tiktok" ? "tiktok" : sp.get("p"), (sp.get("url") || "").trim(), env, req); }
  if (p === "/api/admin/backup" || p === "/api/admin/orders.csv") {
    const a = await auth(req, env); if (!a || !a.admin) return bad("İcazə yoxdur", 403);
    const day = new Date().toISOString().slice(0, 10);
    if (p === "/api/admin/orders.csv") {
      const os = await q("SELECT * FROM orders ORDER BY id");
      const rows = [["ID", "Tarix", "E-poçt", "Xidmət", "Link", "Miqdar", "Məbləğ AZN", "Status"], ...os.map(o => [o.id, new Date(o.date).toISOString(), o.email, o.svc, o.link, o.qty, (o.cost / 100).toFixed(2), o.status])];
      return new Response("\ufeff" + rows.map(r => r.map(csvCell).join(",")).join("\n"), { headers: { "Content-Type": "text/csv; charset=utf-8", "Content-Disposition": "attachment; filename=sifarisler-" + day + ".csv", "Cache-Control": "no-store" } });
    }
    const dump = { exported: new Date().toISOString() };
    for (const t of ["users", "orders", "tx", "topups", "services", "events", "logs"]) dump[t] = await q("SELECT * FROM " + t);
    return new Response(JSON.stringify(dump), { headers: { "Content-Type": "application/json", "Content-Disposition": "attachment; filename=lux-panel-yedek-" + day + ".json", "Cache-Control": "no-store" } });
  }
  if (!post) return bad("Tapılmadı", 404);

  if (p === "/api/register") {
    if (await limited(env, req)) return bad("Çox cəhd. Bir az sonra yenidən yoxlayın", 429);
    const un = String(b.name || "").trim(), lu = un.toLowerCase(), em = String(b.email || "").trim().toLowerCase(), pw = String(b.pass || "");
    if (!/^[A-Za-z0-9_.]{3,20}$/.test(un)) return bad("İstifadəçi adı 3-20 simvol olmalıdır (hərf, rəqəm, _ və .)");
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em) || em.length > 100) return bad("E-poçt düzgün deyil");
    if (pw.length < 8 || pw.length > 100) return bad("Şifrə minimum 8 simvol olmalıdır");
    if (lu === (env.ADMIN_USER || "").trim().toLowerCase()) return bad("Bu istifadəçi adı ayrılıb");
    if (await DB.prepare("SELECT 1 FROM users WHERE username=? OR email=? OR username=? OR email=?").bind(lu, em, em, lu).first()) return bad("Bu istifadəçi adı və ya e-poçt artıq var");
    const r = await DB.prepare("INSERT INTO users(name,username,email,pass,bal,admin,created) VALUES(?,?,?,?,0,0,?)").bind(un, lu, em, await hash(pw, env), Date.now()).run();
    await log(env, r.meta.last_row_id, "register", req);
    return J({ ok: 1, admin: false }, 200, { "Set-Cookie": await startSession(env, r.meta.last_row_id) });
  }
  if (p === "/api/login") {
    if (await limited(env, req)) return bad("Çox cəhd. Bir az sonra yenidən yoxlayın", 429);
    const idn = String(b.login || "").trim().toLowerCase(), pw = String(b.pass || ""), au = (env.ADMIN_USER || "").trim().toLowerCase();
    if (au && idn === au) { try { await ensureAdmin(env); } catch (e) { await logErr(env, "error", "Admin qurulumu: " + e.message); return bad("Admin hesabı düzgün qurulmayıb. Cloudflare-də ADMIN_USER və güclü ADMIN_PASS (min 12 simvol) yoxlayın", 500); } }
    const u = await DB.prepare("SELECT * FROM users WHERE username=? OR email=?").bind(idn, idn).first();
    if (!(await check(pw, u ? u.pass : "p$" + ITER(env) + "$" + "00".repeat(16) + "$" + "00".repeat(32))) || !u) return bad("İstifadəçi adı/e-poçt və ya şifrə səhvdir", 401);
    if (u.blocked === 1) return bad("Hesab dayandırılıb. Dəstəyə müraciət edin", 403);
    if (+String(u.pass).split("$")[1] < ITER(env)) await DB.prepare("UPDATE users SET pass=? WHERE id=?").bind(await hash(pw, env), u.id).run();
    await log(env, u.id, "login", req);
    return J({ ok: 1, admin: u.admin === 1 }, 200, { "Set-Cookie": await startSession(env, u.id) });
  }
  if (p === "/api/logout") {
    const m = /(?:^|; )sid=([a-f0-9]+)/.exec(req.headers.get("Cookie") || ""), u = await auth(req, env);
    if (u) await log(env, u.id, "logout", req);
    if (m) await DB.prepare("DELETE FROM sessions WHERE h=?").bind(await sha256(m[1])).run();
    return J({ ok: 1 }, 200, { "Set-Cookie": "sid=; Path=/; Max-Age=0" });
  }

  const u = await auth(req, env); if (!u) return bad("Daxil olun", 401);

  if (p === "/api/seen") { await DB.prepare("UPDATE users SET seen_at=? WHERE id=?").bind(Date.now(), u.id).run(); return J({ ok: 1 }); }
  if (p === "/api/password") {
    const nw = String(b.pw || "");
    if (!(await check(String(b.old || ""), u.pass))) return bad("Cari şifrə səhvdir");
    if (nw.length < 8 || nw.length > 100) return bad("Yeni şifrə min 8 simvol olmalıdır");
    await DB.prepare("UPDATE users SET pass=? WHERE id=?").bind(await hash(nw, env), u.id).run(); await log(env, u.id, "pwchange", req);
    return J({ ok: 1 });
  }
  if (p === "/api/order") {
    if (u.admin) return bad("Admin sifariş verə bilməz");
    if (await limited(env, req, "o" + u.id + ":", 30)) return bad("Çox sifariş cəhdi. Bir az sonra yenidən yoxlayın", 429);
    const s = await DB.prepare("SELECT * FROM services WHERE id=?").bind(+b.svc).first(), link = String(b.link || "").trim();
    if (!s) return bad("Xidmət tapılmadı");
    const fixed = s.fixed === 1, qty = fixed ? 1 : Math.floor(+b.qty), acct = String(b.acct || "").trim().replace(/^@/, "").slice(0, 60), note = String(b.note || "").trim().slice(0, 200);
    if (/[\u0000-\u001f\u007f]/.test(acct + note)) return bad("İstifadəçi adı və ya qeyd düzgün deyil");
    if (link.length < 3 || link.length > 300 || /[\u0000-\u001f\u007f]/.test(link)) return bad("Link düzgün deyil");
    if (!(qty >= s.min && qty <= s.max)) return bad("Miqdar " + s.min + "–" + s.max + " arası olmalıdır");
    const cost = fixed ? s.price : Math.round(s.price * qty / 1000);
    const r = await DB.batch([
      DB.prepare("UPDATE users SET bal=bal-? WHERE id=? AND bal>=?").bind(cost, u.id, cost),
      DB.prepare("INSERT INTO orders(uid,email,date,svc,link,qty,cost,status,upd,acct,note) SELECT ?,?,?,?,?,?,?,'Gözləyir',0,?,? WHERE changes()>0").bind(u.id, u.email, Date.now(), s.pf + " " + s.name, link, qty, cost, acct, note)]);
    if (!r[0].meta.changes) return bad("Balans kifayət etmir");
    return J({ ok: 1 });
  }
  if (p === "/api/topup") {
    const a = Math.round(Number(b.amt) * 100);
    if (!(a >= 100 && a <= 100000)) return bad("Məbləğ 1–1000 AZN arası olmalıdır");
    if (!env.EPOINT_PUBLIC_KEY || !env.EPOINT_PRIVATE_KEY || !env.SITE_URL) return bad("Ödəniş sistemi hələ qoşulmayıb", 503);
    if (await limited(env, req, "t" + u.id + ":", 10)) return bad("Çox cəhd. Bir az sonra yenidən yoxlayın", 429);
    const tid = "LP" + Date.now().toString(36) + hex(crypto.getRandomValues(new Uint8Array(3)));
    await DB.prepare("INSERT INTO topups(id,uid,amt,status,date) VALUES(?,?,?,'pending',?)").bind(tid, u.id, a, Date.now()).run();
    const site = env.SITE_URL.replace(/\/$/, "");
    const data = btoa(JSON.stringify({ public_key: env.EPOINT_PUBLIC_KEY, amount: a / 100, currency: "AZN", language: "az", order_id: tid, description: "Lux Panel balans artirma", success_redirect_url: site + "/#success", error_redirect_url: site + "/#error" }));
    try {
      const r = await fetch("https://epoint.az/api/1/request", { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ data, signature: await sign(env, data) }) });
      const j = await r.json();
      if (j && j.redirect_url) return J({ url: j.redirect_url });
      await logErr(env, "error", "ePoint sorğu cavabı: " + JSON.stringify(j).slice(0, 300)); return bad("Ödəniş səhifəsi açılmadı", 502);
    } catch (e) { await logErr(env, "error", "ePoint əlaqə xətası: " + e.message); return bad("Ödəniş sistemi ilə əlaqə alınmadı", 502); }
  }

  if (!u.admin) return bad("İcazə yoxdur", 403);

  if (p === "/api/admin/status") {
    const o = await DB.prepare("SELECT * FROM orders WHERE id=?").bind(+b.id).first();
    if (!o || !ST.includes(b.status)) return bad("Yanlış sorğu");
    if (o.status === b.status) return J({ ok: 1 });
    if (o.status === "Ləğv edildi") return bad("Ləğv olunmuş sifarişi bərpa etmək olmur");
    if (b.status === "Ləğv edildi") await DB.batch([
      DB.prepare("UPDATE orders SET status='Ləğv edildi',upd=? WHERE id=? AND status<>'Ləğv edildi'").bind(Date.now(), o.id),
      DB.prepare("UPDATE users SET bal=bal+? WHERE id=? AND changes()>0").bind(o.cost, o.uid)]);
    else await DB.prepare("UPDATE orders SET status=?,upd=? WHERE id=?").bind(b.status, Date.now(), o.id).run();
    return J({ ok: 1 });
  }
  if (p === "/api/admin/balance") {
    const amt = Math.round(Number(b.amt) * 100); if (!amt) return bad("Yanlış sorğu");
    const r = await DB.prepare("UPDATE users SET bal=bal+? WHERE id=? AND admin=0 AND bal+?>=0").bind(amt, +b.uid, amt).run();
    return r.meta.changes ? J({ ok: 1 }) : bad("Balans mənfi ola bilməz və ya istifadəçi tapılmadı");
  }
  if (p === "/api/admin/reset") {
    const t = await DB.prepare("SELECT id FROM users WHERE id=? AND admin=0").bind(+b.uid).first(); if (!t) return bad("İstifadəçi tapılmadı");
    const al = "abcdefghjkmnpqrstuvwxyz23456789", temp = [...crypto.getRandomValues(new Uint8Array(8))].map(x => al[x % al.length]).join("");
    await DB.batch([DB.prepare("UPDATE users SET pass=? WHERE id=?").bind(await hash(temp, env), t.id), DB.prepare("DELETE FROM sessions WHERE uid=?").bind(t.id)]);
    await log(env, t.id, "reset", req); return J({ ok: 1, temp });
  }
  if (p === "/api/admin/block") {
    const t = await DB.prepare("SELECT id FROM users WHERE id=? AND admin=0").bind(+b.uid).first(); if (!t) return bad("İstifadəçi tapılmadı");
    const bl = b.blocked ? 1 : 0;
    await DB.batch([DB.prepare("UPDATE users SET blocked=? WHERE id=?").bind(bl, t.id), DB.prepare("DELETE FROM sessions WHERE uid=? AND ?=1").bind(t.id, bl)]);
    await log(env, t.id, bl ? "block" : "unblock", req); return J({ ok: 1 });
  }
  if (p === "/api/admin/service") {
    if (b.op === "delete") { await DB.prepare("DELETE FROM services WHERE id=?").bind(+b.id).run(); return J({ ok: 1 }); }
    const fixed = b.fixed ? 1 : 0, pf = String(b.pf || "").trim().slice(0, 40), name = String(b.name || "").trim().slice(0, 100), price = Math.round(Number(b.price) * 100);
    const min = fixed ? 1 : Math.floor(+b.min), max = fixed ? 1 : Math.floor(+b.max);
    if (!pf || !name || !(price > 0) || !(min > 0) || !(max >= min)) return bad("Məlumatlar düzgün deyil");
    if (b.op === "create") await DB.prepare("INSERT INTO services(id,pf,name,price,min,max,fixed) SELECT COALESCE(MAX(id),0)+1,?,?,?,?,?,? FROM services").bind(pf, name, price, min, max, fixed).run();
    else await DB.prepare("UPDATE services SET pf=?,name=?,price=?,min=?,max=?,fixed=? WHERE id=?").bind(pf, name, price, min, max, fixed, +b.id).run();
    return J({ ok: 1 });
  }
  return bad("Tapılmadı", 404);
}
